// Binding types are generated by `wrangler types` into worker-configuration.d.ts
// (D1 database, VAPID_PUBLIC_KEY, VAPID_SUBJECT vars). Only *secrets* — which the
// generator cannot know about — are declared here.
export type Bindings = Env & {
  /** Shared secret required by the backend in the Authorization header. */
  BACKEND_AUTH_TOKEN: string;
  /** VAPID private key (Wrangler secret). Never in wrangler.jsonc or source. */
  VAPID_PRIVATE_KEY: string;
};
